function warmerWait(temps) {
    const wait = new Array(temps.length).fill(0);
    for (let day = 0; day < temps.length; day++) {
        for (let later = day + 1; later < temps.length; later++) {
            if (temps[later] > temps[day]) {
                wait[day] = later - day;
                break;
            }
        }
    }
    return wait;
}

function warmerWait(temps) {
    const wait = new Array(temps.length).fill(0);
    const pending = [];
    for (let day = 0; day < temps.length; day++) {
        while (pending.length > 0 && temps[pending[pending.length - 1]] < temps[day]) {
            const earlier = pending.pop();
            wait[earlier] = day - earlier;
        }
        pending.push(day);
    }
    return wait;
}
